package fixture

import (
	"errors"
	"fmt"
	"go/token"
	"os"
	"strings"

	"github.com/goccy/go-yaml/ast"
	"github.com/goccy/go-yaml/parser"

	"github.com/moznion/go-datlas/internal/generator/naming"
)

// policyFile is a parsed fixture policy file, which gives the fixture policy of types
// whose source cannot be edited, such as types generated by other tools.
//
//	types:
//	  - type: example.com/app/db/gen.InsertUserParams
//	    name: User
//	    fields:
//	      Email: email
//	      Note: "-"
type policyFile struct {
	Path  string
	Types []policyType
}

// policyType is an entry of a policy file.
type policyType struct {
	Pos token.Position
	// PkgPath and TypeName split the "type" value "import/path.Name".
	PkgPath  string
	TypeName string
	// Name and Plural rename the factory methods; empty means the default.
	Name   string
	Plural string
	// Fields maps field names to policies written in the struct tag grammar.
	Fields   map[string]string
	FieldPos map[string]token.Position
}

// packages returns the import paths the policy file refers to:
// the packages of its types and of qualified wrap and gen functions.
func (pf *policyFile) packages() []string {
	var paths []string
	for _, pt := range pf.Types {
		paths = append(paths, pt.PkgPath)
		for _, p := range pt.Fields {
			if policy, err := parseTag(p); err == nil {
				if path, _ := splitQualified(policy.Params["wrap"]); path != "" {
					paths = append(paths, path)
				}
				if policy.Generator == "gen" && len(policy.Candidates) == 1 {
					if path, _ := splitQualified(policy.Candidates[0]); path != "" {
						paths = append(paths, path)
					}
				}
			}
		}
	}
	return paths
}

// splitQualified splits "import/path.Name" into its package path and name.
// An unqualified name has an empty package path.
func splitQualified(ref string) (pkgPath, name string) {
	if i := strings.LastIndex(ref, "."); i > strings.LastIndex(ref, "/") {
		return ref[:i], ref[i+1:]
	}
	return "", ref
}

// parsePolicyFile reads and validates the policy file at path.
func parsePolicyFile(path string) (*policyFile, error) {
	src, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	f, err := parser.ParseBytes(src, 0)
	if err != nil {
		return nil, fmt.Errorf("%s: malformed YAML:\n%w", path, err)
	}
	p := &policyParser{path: path}
	pf := &policyFile{Path: path}
	var body ast.Node
	for _, d := range f.Docs {
		if d.Body != nil {
			if body != nil {
				return nil, fmt.Errorf("%s: expected a single YAML document", path)
			}
			body = d.Body
		}
	}
	if body == nil {
		return pf, nil
	}
	for _, kv := range p.mapping(body, "the policy file") {
		switch key := p.key(kv); key {
		case "types":
			seq, ok := kv.Value.(*ast.SequenceNode)
			if !ok {
				p.errorf(kv.Value, "types must be a sequence, got %s", describe(kv.Value))
				continue
			}
			for _, item := range seq.Values {
				if pt, ok := p.entry(item); ok {
					pf.Types = append(pf.Types, pt)
				}
			}
		case "":
		default:
			p.errorf(kv.Key, "unknown key %q (available: types)", key)
		}
	}
	if err := errors.Join(p.errs...); err != nil {
		return nil, err
	}
	return pf, nil
}

type policyParser struct {
	path string
	errs []error
}

func (p *policyParser) pos(n ast.Node) token.Position {
	pos := token.Position{Filename: p.path}
	if n != nil {
		if tk := n.GetToken(); tk != nil && tk.Position != nil {
			pos.Line, pos.Column = tk.Position.Line, tk.Position.Column
		}
	}
	return pos
}

func (p *policyParser) errorf(n ast.Node, format string, args ...any) {
	p.errs = append(p.errs, fmt.Errorf("%s: %s", p.pos(n), fmt.Sprintf(format, args...)))
}

// mapping returns the entries of the mapping n, reporting duplicate keys.
// what names n in error messages.
func (p *policyParser) mapping(n ast.Node, what string) []*ast.MappingValueNode {
	var kvs []*ast.MappingValueNode
	switch m := n.(type) {
	case *ast.MappingNode:
		kvs = m.Values
	case *ast.MappingValueNode:
		kvs = []*ast.MappingValueNode{m}
	default:
		p.errorf(n, "%s must be a mapping, got %s", what, describe(n))
		return nil
	}
	seen := map[string]bool{}
	var result []*ast.MappingValueNode
	for _, kv := range kvs {
		key := p.key(kv)
		if key == "" {
			continue
		}
		if seen[key] {
			p.errorf(kv.Key, "duplicate key %q", key)
			continue
		}
		seen[key] = true
		result = append(result, kv)
	}
	return result
}

// key returns the key of kv, or an empty string after reporting a non-string key.
func (p *policyParser) key(kv *ast.MappingValueNode) string {
	if s, ok := kv.Key.(*ast.StringNode); ok && s.Value != "" {
		return s.Value
	}
	p.errorf(kv.Key, "keys must be non-empty strings")
	return ""
}

// str returns the string value n; what names it in error messages.
func (p *policyParser) str(n ast.Node, what string) (string, bool) {
	if s, ok := n.(*ast.StringNode); ok && s.Value != "" {
		return s.Value, true
	}
	p.errorf(n, "%s must be a non-empty string, got %s", what, describe(n))
	return "", false
}

func (p *policyParser) entry(n ast.Node) (policyType, bool) {
	pt := policyType{Pos: p.pos(n), Fields: map[string]string{}, FieldPos: map[string]token.Position{}}
	nerrs := len(p.errs)
	hasType := false
	for _, kv := range p.mapping(n, "an entry of types") {
		switch key := p.key(kv); key {
		case "type":
			ref, ok := p.str(kv.Value, "type")
			if !ok {
				continue
			}
			hasType = true
			pt.Pos = p.pos(kv.Value)
			pt.PkgPath, pt.TypeName = splitQualified(ref)
			if pt.PkgPath == "" || !naming.IsIdentifier(pt.TypeName) {
				p.errorf(kv.Value, "type %q must be an import path followed by a type name, e.g. example.com/app/db.User", ref)
			}
		case "name", "plural":
			v, ok := p.str(kv.Value, key)
			if !ok {
				continue
			}
			if !naming.IsIdentifier(v) || token.IsKeyword(v) {
				p.errorf(kv.Value, "%s %q is not a valid Go identifier", key, v)
			}
			if key == "name" {
				pt.Name = v
			} else {
				pt.Plural = v
			}
		case "fields":
			if _, ok := kv.Value.(*ast.NullNode); ok {
				continue
			}
			for _, f := range p.mapping(kv.Value, "fields") {
				name := p.key(f)
				v, ok := p.str(f.Value, "the policy of "+name)
				if !ok {
					continue
				}
				pt.Fields[name] = v
				pt.FieldPos[name] = p.pos(f.Key)
			}
		case "":
		default:
			p.errorf(kv.Key, "unknown key %q (available: type, name, plural, fields)", key)
		}
	}
	if !hasType && len(p.errs) == nerrs {
		p.errorf(n, "an entry of types needs a type")
	}
	return pt, len(p.errs) == nerrs
}

func describe(n ast.Node) string {
	switch n.(type) {
	case nil:
		return "nothing"
	case *ast.NullNode:
		return "null"
	case *ast.StringNode, *ast.LiteralNode:
		return "a string"
	case *ast.IntegerNode:
		return "an integer"
	case *ast.FloatNode, *ast.InfinityNode, *ast.NanNode:
		return "a float"
	case *ast.BoolNode:
		return "a bool"
	case *ast.SequenceNode:
		return "a sequence"
	case *ast.MappingNode, *ast.MappingValueNode:
		return "a mapping"
	case *ast.AnchorNode, *ast.AliasNode:
		return "an anchor or alias (not supported here)"
	case *ast.TagNode:
		return "a tagged value (not supported here)"
	default:
		return fmt.Sprintf("%T", n)
	}
}
